1379:/// Check a log's first line: it must be the `run-start` header, of this
1380:/// format and a version this build reads (reviews cr-jl1a-2, cr-jlfix1-1).
1381:/// Read as untyped JSON, so a newer header's fields are never forced into
1382:/// this version's shape. Anything else — another kind, a damaged or missing
1383:/// first line, a file that is not a job log — is refused rather than read
1384:/// as the current version; [`decode`] shows such a file's lines as stored.
1385:/// (Recovery gives a log whose start was lost a header of its own.)
1386:fn check_header(line: &[u8]) -> io::Result<()> {
1387:    use serde_json::Value;
1388:    let invalid = |message: String| Err(io::Error::new(io::ErrorKind::InvalidData, message));
1389:    let not_a_log = || {
1390:        invalid(
1391:            "not a blit job log, or its first line is damaged \
1392:             (`blit jobs log --json` shows its lines as stored)"
1393:                .into(),
1394:        )
1395:    };
1396:    let Ok(Value::Object(header)) = serde_json::from_slice::<Value>(line) else {
1397:        return not_a_log();
1398:    };
1399:    if header.get("kind").and_then(Value::as_str) != Some("run-start") {
1400:        return not_a_log();
1401:    }
1402:    let format = header.get("format").and_then(Value::as_str).unwrap_or("");
1403:    if format != FORMAT {
1404:        return invalid(format!("not a blit job log (format {format:?})"));
1405:    }
1406:    // Review cr-jlfix2-1: only versions this build knows, each parsed whole
1407:    // as that version's `run-start`. Version 1 is the only one so far; when
1408:    // VERSION moves past it, each older version gets its own arm (and its
1409:    // migration).
1410:    match header.get("version").and_then(Value::as_u64) {
1411:        Some(1) => match serde_json::from_slice::<Event>(line) {
1412:            Ok(Event {
1413:                body: EventBody::RunStart(_),
1414:                ..
1415:            }) => Ok(()),
1416:            _ => invalid(
1417:                "the job log's run-start is incomplete or damaged \
1418:                 (`blit jobs log --json` shows its lines as stored)"
1419:                    .into(),
1420:            ),
1421:        },
1422:        Some(version) if version > u64::from(VERSION) => invalid(format!(
1423:            "this job log is version {version}; this blit reads versions up to {VERSION} \
1424:             (`blit jobs log --json` shows it as stored)"
1425:        )),
1426:        Some(version) => invalid(format!(
1427:            "this job log names version {version}, which no blit writes"
1428:        )),
1429:        None => invalid("the job log's run-start names no version".into()),
1430:    }
1431:}
